#!/usr/bin/env bash
# ./briefcase — entry point for the 0-to-1 Agent Skills CLI.
# Generated by install.sh. Do not edit manually.
#
# Keeps project data in the current checkout while allowing linked worktrees
# to share the main checkout's framework installation.

set -euo pipefail

find_project_root() {
    local dir git_root
    dir="$(cd "${1:-.}" && pwd -P)"
    git_root="$(git -C "$dir" rev-parse --show-toplevel 2>/dev/null)" || git_root=""
    if [ -n "$git_root" ]; then
        git_root="$(cd "$git_root" && pwd -P)"
    fi
    while true; do
        if [ -d "$dir/.briefcase" ] || [ "$dir" = "$git_root" ]; then
            printf '%s\n' "$dir"
            return 0
        fi
        local parent
        parent="$(dirname "$dir")"
        if [ "$parent" = "$dir" ]; then
            return 1
        fi
        dir="$parent"
    done
}

find_framework_dir() {
    local worktrees first_line main_checkout
    if [ -f "$PROJECT_ROOT/.briefcase/src/cli/main.py" ]; then
        printf '%s\n' "$PROJECT_ROOT/.briefcase"
        return 0
    fi
    if [ -f "$PROJECT_ROOT/.git" ]; then
        worktrees="$(git -C "$PROJECT_ROOT" -c core.quotePath=false worktree list --porcelain)" || return 1
        first_line="${worktrees%%$'\n'*}"
        case "$first_line" in
            "worktree "*) main_checkout="${first_line#worktree }" ;;
            *) return 1 ;;
        esac
        if [ -d "$main_checkout/.briefcase" ]; then
            printf '%s\n' "$main_checkout/.briefcase"
            return 0
        fi
    fi
    return 1
}

PROJECT_ROOT="$(find_project_root "$(pwd)")" || {
    echo "Error: not inside an initialized project." >&2
    echo "No .briefcase/ directory found. Run install.sh first." >&2
    exit 1
}

FRAMEWORK_DIR="$(find_framework_dir)" || {
    echo "Error: no framework installation found for $PROJECT_ROOT." >&2
    echo "Run install.sh in this checkout or its main Git checkout." >&2
    exit 1
}
if [ ! -f "$FRAMEWORK_DIR/src/cli/main.py" ]; then
    echo "Error: incomplete framework installation at $FRAMEWORK_DIR. Run install.sh again." >&2
    exit 1
fi

# --- Select Python interpreter ---
# Preference: .briefcase/.venv > system python3
if [ -x "$FRAMEWORK_DIR/.venv/bin/python" ]; then
    PYTHON="$FRAMEWORK_DIR/.venv/bin/python"
elif command -v python3 >/dev/null 2>&1; then
    PYTHON="python3"
else
    echo "Error: Python 3 not found." >&2
    echo "Install Python 3 or create .briefcase/.venv/." >&2
    exit 1
fi

# --- Bootstrap and run CLI ---
# Insert .briefcase/ at front of sys.path so 'from src.*' resolves
# to .briefcase/src/ per the sys.path contract (D-032).
export BRIEFCASE_PROJECT_ROOT="$PROJECT_ROOT"
exec "$PYTHON" -c '
import sys
sys.path.insert(0, sys.argv.pop(1))
from src.cli.main import cli
cli()
' "$FRAMEWORK_DIR" "$@"
